## 6️⃣ Full Minimal Example (HTML + JS)

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>MapLibre + PMTiles</title>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.js';
  import * as pmtiles from 'https://cdn.jsdelivr.net/npm/pmtiles@2.7.0/dist/index.min.js';

  // 1️⃣ Register protocol
  const protocol = new pmtiles.Protocol();
  maplibregl.addProtocol('pmtiles', protocol.tile);

  // 2️⃣ Create the map
  const map = new maplibregl.Map({
    container: 'map',
    style: {
      version: 8,
      sources: {
        world: {
          type: 'vector',
          url: 'pmtiles://https://example.com/tiles/world.pmtiles'
        }
      },
      layers: [
        {
          id: 'water',
          type: 'fill',
          source: 'world',
          'source-layer': 'water',
          paint: { 'fill-color': '#a0c8f0' }
        },
        {
          id: 'landuse',
          type: 'fill',
          source: 'world',
          'source-layer': 'landuse',
          paint: { 'fill-color': '#e0e0c0' }
        }
      ]
    },
    center: [0, 0],
    zoom: 2
  });
</script>
</body>
</html>
```

*Replace `https://example.com/tiles/world.pmtiles` with the real URL of your file.*

